def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def list_gcd(numbers):
    if not numbers:
        return 0
    result = numbers[0]
    for i in range(1, len(numbers)):
        result = gcd(result, numbers[i])
    return result

def list_lcm(numbers):
    if not numbers:
        return 1
    result = numbers[0]
    for i in range(1, len(numbers)):
        result = lcm(result, numbers[i])
    return result

def count_good_partitions(sequence):
    n = len(sequence)
    count = 0
    for k in range(1, n):
        A_k = sequence[:k]
        B_k = sequence[k:]

        lcm_A = list_lcm(A_k)
        gcd_B = list_gcd(B_k)

        if lcm_A == gcd_B:
            count += 1
    return count

