    if r <= 1:
        raise ValueError("r must be greater than 1")

    a = [r**(i-1) for i in range(1, N + 1)]

    good_count = 0

    # We check partitions for k = 1 to N-1
    for k in range(1, N):
        # A_k = {a_1, ..., a_k}
