        for x in A_k:
            L_k = lcm(L_k, x)

        # Calculate G_k = gcd(B_k)
        G_k = B_k[0]
        for i in range(1, len(B_k)):
            G_k = gcd(G_k, B_k[i])

        # Check condition
        if L_k == G_k:
            good_count += 1

